import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { MessageProcessor, basicCatalog } from '@a2ui/web_core/v1_0'
import { catalogWithOpenUrlOff } from './catalog.js'

// Real MessageProcessor, no mocks: messages are what the plugin stores for a
// present followed by an update of the same surface_id (generated by
// handle_a2ui_render with Express input).
const here = dirname(fileURLToPath(import.meta.url))
const msgs = JSON.parse(readFileSync(resolve(here, 'fixtures/order-lookup.json'), 'utf8'))

describe('real MessageProcessor with stored uirizz messages', () => {
  it('creates the surface under the stored surface_id, then updates it in place', () => {
    const p = new MessageProcessor([basicCatalog], () => {}, { version: '1.0' })
    p.processMessages(msgs.slice(0, 1))
    const surface = p.getSurface('order-lookup')
    expect(surface).toBeTruthy()
    p.processMessages(msgs.slice(1))
    expect(p.getSurface('order-lookup')).toBe(surface)
    expect([...p.getSurfaces().keys()]).toEqual(['order-lookup'])
  })

  it('carries no null wire fields', () => {
    expect(JSON.stringify(msgs)).not.toContain(':null')
  })

  it('the openUrl-off catalog keeps the basic catalog id and creates the surface', () => {
    const catalog = catalogWithOpenUrlOff()
    expect(catalog.id).toBe(basicCatalog.id)
    const p = new MessageProcessor([catalog], () => {}, { version: '1.0' })
    p.processMessages(msgs.slice(0, 1))
    expect(p.getSurface('order-lookup')).toBeTruthy()
  })
})
